```python
from flask import Flask, request, jsonify
app = Flask(__name__)
resources = {} # In-memory storage. This should be replaced with a database in real world applications

@app.route('/resource/<string:id>', methods=['GET'])
def get_resource(id):
    if id not in resources:
        return jsonify({'error': 'Resource not found'}), 404
    else:
        return jsonify(resources[id]), 200

@app.route('/resource/<string:id>', methods=['POST'])
def create_resource(id):
    if id in resources:
        return jsonify({'error': 'Resource already exists'}), 409

    data = request.get_json()
    resources[id] = data

    return jsonify(data), 201
```
