```",94,,"['Here is the Python code you asked for. Please note that this assumes that each file in your directory contains only one line with a sequence number. The files are sorted using their names, and if there's more than one file with the same name but different extensions (like .txt or .doc) then they may interfere with each other:

```python
import os

def extract_sequence_number(file_path):
    try:
        with open(file_path, 'r') as file:
            lines = sorted(file.readlines())
            last_line = lines[-1].strip()
            sequence_number = int(last_line)
            return sequence_number
    except FileNotFoundError as e:
        print(f""Error: File not found - {e}"")
        return None
    except ValueError as e:
        print(f""Error: Invalid sequence number format - {e}"")
        return None

def process_sequence_numbers(directory):
    seq_nums = set()

    for filename in sorted(os.listdir(directory)):

        if filename.endswith('.txt'):
            try:
                with open(os.path.join(directory, filename), 'r') as file:
                    lines = sorted(file.readlines())
                    last_line = lines[-1].strip()

                    if last_line.isdigit():
                        seq_num = int(last_line)
                        seq_nums.add(seq_num)

            except FileNotFoundError:
                print(f""Error while processing {filename} - File not found"")
                continue

            except ValueError:
                print(f""Error while processing {filename} - Invalid number format"")
                continue

    return sorted(list(seq_nums))

directory_path = 'sequence_directories'
sorted_unique_nums = process_sequence_numbers(directory_path)
print(sorted_unique_nums)
```
This will print a list of unique sequence numbers from all .txt files in the specified directory, sorted by their integer value. If there are any issues with reading or parsing files, it will catch these and print an error message without stopping execution. It also prints an error if a file can't be found.
