from Crypto.Cipher import AES
from Crypto.Util.Padding import unpad

def aes_decrypt(ciphertext, key, iv):
    cipher = AES.new(key, AES.MODE_CBC, iv)
    plaintext = unpad(cipher.decrypt(ciphertext), AES.block_size)
    return list(plaintext)

def sort_descending(data):
    return sorted(data, reverse=True)

def decrypt_and_sort(encrypted_data, key, iv, limit):
    try:
        decrypted_data = aes_decrypt(encrypted_data, key, iv)

        if len(decrypted_data) <= limit:
            return sort_descending(decrypted_data)
        else:
            return []

