import hashlib
import os
import requests

def HashAndPublishArticle(directory_path, api_credentials):
    def process_draft(file_path):
        with open(file_path, 'r') as f:
            article_content = f.read()
        hashed_content = hashlib.md5(article_content.encode()).hexdigest()

        headers = {
            'Content-Type': api_credentials['content_type'], 
            'Authorization': api_credentials['authorization']
        }
        body = {
            'title': os.path.basename(file_path), 
            'body': hashed_content
        }

        try:
            response = requests.post(api_credentials['endpoint'], headers=headers, data=body)
            if response.status_code == 200:
                return ""Article published successfully""
            else:
                return f""Failed to publish article. Status code: {response.status_code}""
        except requests.exceptions.RequestException as e:
            return f""An error occurred while publishing the article: {e}""

    publication_results = []

    for filename in os.listdir(directory_path):
        if filename.endswith('.md'):  # Assuming markdown files have .md extension
            file_path = os.path.join(directory_path, filename)
            result = process_draft(file_path)
            publication_results.append(result)

    return publication_results
