import hashlib
from typing import List, Union, Tuple
from multiprocessing import Pool
from hmac import HMAC
from os import urandom

class EnhancedSHA256Util:
    def __init__(self):
        self.hash_algorithms = {'sha256': hashlib.sha256, 'sha384': hashlib.sha384, 
                               'sha512': hashlib.sha512, 'md5': hashlib.md5}

        self.hmac_algorithms = {'HMAC-SHA256': hashlib.sha256, 'HMAC-SHA384': hashlib.sha384, 
                                'HMAC-SHA512': hashlib.sha512}

    def compute_hash(self, input_string: str, encoding: str = 'utf-8', as_hex: bool = False, validate: bool = True, salt: Union[str, bytes] = None, algo: str = 'sha256') -> Tuple[bytes, List[bytes]]:
        if not algo in self.hash_algorithms.keys():
            raise ValueError(f""Unsupported hashing algorithm {algo}"")

        hash_object = self.hash_algorithms[algo](input_string.encode(encoding))

        if salt:
            hash_object.update(salt)

        computed_hash = hash_object.digest()
        known_hashes = [] # add your list of known hashes here

        if validate and any([computed_hash == known for known in known_hashes]):
            return (computed_hash, known_hashes)

        return (computed_hash.hex() if as_hex else computed_hash, known_hashes)

    def compute_md5(self, input_string: str, encoding: str = 'utf-8') -> bytes:
        hash_object = self.hash_algorithms['md5'](input_string.encode(encoding))

        return hash_object.digest()

    def compute_hmac(self, key: Union[str, bytes], input_string: str, encoding: str = 'utf-8', algo: str = 'HMAC-SHA256') -> HMAC:
        if not algo in self.hmac_algorithms.keys():
            raise ValueError(f""Unsupported hmac algorithm {algo}"")

        return HMAC(key, input_string, digestmod=self.hmac_algorithms[algo])

    def find_collision(self, limit: int) -> Tuple[str, str]:
        hashes = {}

        for _ in range(limit):
            random_input = urandom(16) # adjust this as needed
            computed_hash = hashlib.sha256(random_input).digest()

            if computed_hash in hashes:
                return (computed_hash, random_input)

            hashes[computed_hash] = random_input

        raise Exception(""Failed to find a collision"")

    def compare_hashes(self, hash1: bytes, hash2: bytes, ignore_padding: bool = False):
        return (hash1 == hash2) if ignore_padding else (hash1.strip('='.encode()) == hash2.strip('='.encode()))

    def multithreaded_hashing(self, data: List[str], algo: str = 'sha256') -> List[bytes]:
        with Pool() as p:
            return p.map(lambda s: self.compute_hash(s, algo=algo)[0], data)
```
