            filtered_img = self._apply_gaussian_blur(img)

            # You could add this to a cache here, or update an existing entry if applicable
            processed_images.append(filtered_img)
        return processed_images

    def _apply_gaussian_blur(self, image):
        radius = self.config.get('filter_radius', 2)
        return filters.gaussian(image, sigma=radius)

