import random

class Graph:
    def __init__(self):
        self.vertices = {}
        self.edges = {}

    def add_vertex(self, id, properties={}):
        self.vertices[id] = properties

    def add_edge(self, source_id, target_id, weight=1):
        if source_id in self.vertices and target_id in self.vertices:
            self.edges[(source_id, target_id)] = weight

    def remove_vertex(self, id):
        if id in self.vertices:
            del self.vertices[id]
            for edge in list(self.edges.keys()):
                if edge[0] == id or edge[1] == id:
                    del self.edges[edge]

    def remove_edge(self, source_id, target_id):
        if (source_id, target_id) in self.edges:
            del self.edges[(source_id, target_id)]

class ComplexGraph(Graph):
    factory_registry = {}

    @staticmethod
    def register_factory(factory_function):
        ComplexGraph.factory_registry[factory_function.__name__] = factory_function

    @staticmethod
    def unregister_factory(factory_name):
        del ComplexGraph.factory_registry[factory_name]

    @staticmethod
    def create_instance(factory_name, vertex_properties=None):
        return ComplexGraph.factory_registry[factory_name](vertex_properties)

    def add_vertex(self, id, properties=None):
        if properties is None:
            properties = {}
        super().add_vertex(id=id, properties=properties)

    def add_edge(self, source_id: str | int, target_id: str | int, weight: float | int | None = 1, relation_type: str | None = None):
        super().add_edge(source_id=source_id, target_id=target_id, weight=weight)

        if relation_type is not None:
            try:
                ComplexGraph.register_factory(lambda x: (source_id, target_id))
                print(f""Relationship type '{relation_type}' registered."")
            except Exception as e:
                print(f""Error registering relationship type '{relation_type}': {e}"")

class VertexFactory():
    _vertex_types = {
        'default': (lambda x: {'name': x, 'age': random.randint(18, int(90))}),
        'worker': (lambda x: {'name': x, 'age': random.randint(20, int(65)), 'job': 'worker', 'interests': ['work', 'finance']}),
        'student': (lambda x: {'name': x, 'age': random.randint(18, int(30)), 'school': None, 'subjects': []})
    }

    @staticmethod
    def create_vertex(type='default', properties=None):
        if type not in VertexFactory._vertex_types:
            raise ValueError(""Invalid vertex type"")

        return VertexFactory._vertex_types[type](properties)
