def modify_dict(dictionary, new_key, new_values, existing_key=None):
    if existing_key in dictionary:
        index = list(dictionary.keys()).index(existing_key)
        keys = list(dictionary.keys())
        values = list(dictionary.values())
        keys.insert(index + 1, new_key)
        values.insert(index + 1, new_values)
        dictionary.clear()
        for key, value in zip(keys, values):
            dictionary[key] = value
    else:
        dictionary[new_key] = new_values
