import os
import hashlib
from threading import Thread, active_count

def compute_sha256_hash(file_path, chunk_size=1024):
    with open(file_path, 'rb') as file:
        data_chunks = [file.read(chunk_size) for _ in range(os.cpu_count() or 1)]
        hash_object = hashlib.sha256()
        for chunk in data_chunks:
            if chunk:
                hash_object.update(chunk)

        return hash_object.hexdigest()

def process_directory(directory_path):
    file_hashes = {}

    for root, dirs, files in os.walk(directory_path):
        for filename in files:
            full_file_path = os.path.join(root, filename)
            computed_hash = compute_sha256_hash(full_file_path)
            file_hashes[full_file_path] = computed_hash

    return file_hashes

def verify_file_integrity(file_hashes):
    for file, hash in file_hashes.items():
        if compute_sha256_hash(file) != hash:
            print('File Integrity Failed')
            return 

    print('File Integrity Verified')
