Ensure thorough documentation of code changes and unit tests covering all new functionalities added.",327,,"[""Here's a basic implementation in Python that satisfies the requirements you've listed. The use of `hashlib` library allows us to compute SHA256, SHA512, and MD5 hashes.

```python
import hashlib
from typing import Optional, List
from multiprocessing import Pool
import os
import hmac

class EnhancedSHA256Util:
    @staticmethod
    def computeHash(input_str: str, encoding: str = 'utf-8', hexadecimal: bool = False, validate_list: Optional[List] = None):
        if not isinstance(input_str, str) or not isinstance(encoding, str) or not isinstance(hexadecimal, bool):
            raise ValueError('Invalid input parameters')

        hash_object = hashlib.sha256()
        hash_object.update(input_str.encode(encoding))
        if validate_list and hash_object.digest() not in [hashlib.sha256(i.encode()).digest() for i in validate_list]:
            raise ValueError('Hash validation failed')

        return hash_object.hexdigest() if hexadecimal else hash_object.digest()

    @staticmethod
    def computeMD5Hash(input_str: str, encoding: str = 'utf-8', hexadecimal: bool = False):
        if not isinstance(input_str, str) or not isinstance(encoding, str) or not isinstance(hexadecimal, bool):
            raise ValueError('Invalid input parameters')

        hash_object = hashlib.md5()
        hash_object.update(input_str.encode(encoding))

        return hash_object.hexdigest() if hexadecimal else hash_object.digest()

    @staticmethod
    def computeHashWithSalt(input_str: str, salt: str, encoding: str = 'utf-8', hexadecimal: bool = False):
        if not isinstance(input_str, str) or not isinstance(encoding, str) or not isinstance(hexadecimal, bool) or not isinstance(salt, str):
            raise ValueError('Invalid input parameters')

        hash_object = hashlib.sha256()
        hash_object.update((input_str + salt).encode(encoding))

        return hash_object.hexdigest() if hexadecimal else hash_object.digest()

    @staticmethod
    def computeHashInParallel(data: List[str], encoding: str = 'utf-8', hexadecimal: bool = False):
        if not all(isinstance(i, str) for i in data) or not isinstance(encoding, str) or not isinstance(hexadecimal, bool):
            raise ValueError('Invalid input parameters')

        with Pool() as pool:
            results = pool.map(EnhancedSHA256Util.computeHash, [(i, encoding, hexadecimal) for i in data])

        return results

    @staticmethod
    def computeHMAC(key: str, message: str, algorithm: str = 'sha256'):
        if not isinstance(key, str) or not isinstance(message, str) or not isinstance(algorithm, str):
            raise ValueError('Invalid input parameters')

        if algorithm.lower() == 'sha256':
            digest_maker = hmac.new(key.encode(), message.encode(), hashlib.sha256).digest()
        elif algorithm.lower() == 'sha512':
            digest_maker = hmac.new(key.encode(), message.encode(), hashlib.sha512).digest()
        else:
            raise ValueError('Unsupported HMAC algorithm')

        return digest_maker.hex()

    @staticmethod
    def detectCollision():
        while True:
            input_str = os.urandom(32)
            hash_object1 = hashlib.sha256(input_str).digest()

            for _ in range(1000):
                input_str = os.urandom(32)
                hash_object2 = hashlib.sha256(input_str).digest()

                if hash_object1 == hash_object2:
                    return 'Collision detected!'
```
