```python
from Crypto.Cipher import AES, DES, PKCS1_OAEP
from Crypto.PublicKey import RSA
from Crypto.Random import get_random_bytes
from Crypto.Hash import HMAC, SHA256
import hashlib
import base64
import os
import threading

class AdvancedEncryptionManager:
    def __init__(self):
        self._supported_algorithms = ['aes', 'des', 'rsa']

    # Key management methods omitted for brevity.

    def _check_algorithm(self, algorithm):
        if algorithm not in self._supported_algorithms:
            raise ValueError(""Unsupported encryption algorithm."")

    def encrypt(self, data, key, algorithm='aes', mode=None):
        self._check_algorithm(algorithm)

        # Ensure that the provided data is bytes.
        if not isinstance(data, bytes):
            data = str(data).encode()

        if algorithm == 'aes':
            cipher = AES.new(key, mode or AES.MODE_EAX)
            encrypted_text, tag = cipher.encrypt_and_digest(data)
            return {'cipher_text': base64.b64encode(cipher.nonce + tag + encrypted_text).decode(), 'tag': base64.b64encode(tag).decode()}

        if algorithm == 'des':
            cipher = DES.new(key, mode or DES.MODE_ECB)
            return {'cipher_text': base64.b64encode(cipher.encrypt(data)).decode()}

        if algorithm == 'rsa':
            rsa_key = RSA.importKey(key)
            cipher = PKCS1_OAEP.new(rsa_key)
            return {'cipher_text': base64.b64encode(cipher.encrypt(data)).decode()}

    def decrypt(self, encrypted_data, key, algorithm='aes', mode=None):
        self._check_algorithm(algorithm)

        if algorithm == 'aes':
            cipher = AES.new(key, mode or AES.MODE_EAX, nonce=base64.b64decode(encrypted_data['nonce']))
            decrypted_text = cipher.decrypt(base64.b64decode(encrypted_data['cipher_text']))
            try:
                cipher.verify(base64.b64decode(encrypted_data['tag']))
                return decrypted_text
            except ValueError:
                raise ValueError(""Decryption failed."")

        if algorithm == 'des':
            cipher = DES.new(key, mode or DES.MODE_ECB)
            return cipher.decrypt(base64.b64decode(encrypted_data['cipher_text']))

        if algorithm == 'rsa':
            rsa_key = RSA.importKey(key)
            cipher = PKCS1_OAEP.new(rsa_key)
            return cipher.decrypt(base64.b64decode(encrypted_data['cipher_text']))

    def hmac_digest(self, data, key):
        hash = HMAC.new(key, digestmod=SHA256)
        hash.update(data)
        return base64.b64encode(hash.digest()).decode()

    # Multi-threaded encryption and decryption methods omitted for brevity. 
