import hashlib
import os
import ctypes
from ctypes import c_char_p, c_void_p, cast, POINTER

# Load the shared library
encrypt = ctypes.CDLL(""./encrypt.so"")

def calculate_md5(file_path, chunk_size=8192):
    h = hashlib.new('md5')

    with open(file_path,'rb') as f: 
        while True:
            # Reading is buffered, so we can read smaller chunks.
            chunk = f.read(chunk_size)
            if len(chunk) == 0:
                return h.hexdigest()
            h.update(chunk)

def encrypt_md5(hash_value):
    # Convert hash to bytes
    hash_bytes = bytearray(hash_value, 'utf-8')

    # Encrypt using OpenSSL
    encrypted_data = encrypt.encrypt(hash_bytes)

    return bytes(cast(encrypted_data, POINTER(c_char)).contents)

def save_encrypted_data(encrypted_data, output_file):
    with open(output_file, 'wb') as file:
        file.write(encrypted_data)
