```python
import hashlib
from ctypes import cdll

# Load C library
process_transactions = cdll.LoadLibrary('./process_transactions.so')

class Transaction:
    def __init__(self, transaction_id, age, recent_activity):
        self.transaction_id = transaction_id
        self.age = age
        self.recent_activity = recent_activity

    # Generate MD5 hash for security
    def generate_hash(self):
        data = f""{self.transaction_id}{self.age}{self.recent_activity}""
        return hashlib.md5(data.encode()).hexdigest()
```

