This task involves creating a class that can parse a filename to extract a numeric range, generate random numbers based on that range, and compute an MD5 hash for a file specified in the filename.",338,,"['Here is the python code block implementing this functionality:

```python
import re
import os
import random
import hashlib
from typing import Tuple

class FileHashGenerator:
    def __init__(self, filename):
        self._filename = filename
        self.range_start, self.range_end = self._extract_range()

    def _extract_range(self) -> Tuple[int, int]:
        match = re.search('(\d+)-(\d+)\.\w+', self._filename)
        if not match:
            raise ValueError(""Invalid filename format"")
        return (int(match.group(1)), int(match.group(2)))

    def _generate_random_float(self):
        return random.uniform(self.range_start, self.range_end)

    def _generate_random_integer(self):
        return round(random.uniform(self.range_start*10, self.range_end*10))/10

    @property
    def md5hash(self):
        if not os.path.isfile(self._filename):
            raise FileNotFoundError(""File does not exist"")

        with open(self._filename,'rb') as f:
            bytes = f.read() 
            hash = hashlib.md5(bytes).hexdigest()

        return hash

# Initiating class instance and printing the desired output
file_handler = FileHashGenerator(""example-25.txt"")
print(f""MD5 Hash: {file_handler.md5hash}"")
print(f""Random floating point number: {file_handler._generate_random_float()}"")
print(f""Scaled random integer: {file_handler._generate_random_integer()}"")
``` 

This code assumes that the filename format always ends with "".txt"", and that if the range is given as ""25-30"", it means integers within this range are to be generated, not floating point numbers. If you want to generate floating point number from the same range, change the `_generate_random_float` method accordingly.
