Here is a very basic implementation using Python:

```python
import uuid
import hashlib
from random import randint, choice

class EnhancedGraphGenerator:
    def __init__(self):
        self.graph = {}

    # Graph Generation
    def generate_vertex(self):
        return {
            'uuid': str(uuid.uuid4()), 
            'property1': randint(1, 100),
            'name': 'Person'+str(randint(1, 100)),
            'age': randint(20, 80),
            'interests': ['Interest'+str(randint(1, 100)) for _ in range(5)],
        }

    def add_vertex(self):
        vertex = self.generate_vertex()
        self.graph[vertex['uuid']] = {**vertex, 'edges': []}

    # Edge Creation
    def add_edge(self, uuid1, uuid2, relationship):
        if (uuid1 in self.graph) and (uuid2 in self.graph):
            edge = {'uuid': uuid2, 'relationship': relationship, 'since_year': randint(1970, 2022)}
            self.graph[uuid1]['edges'].append(edge)

    # Hashing Capabilities
    def hash_vertex(self, uuid, salt=None):
        vertex = self.graph[uuid]
        properties = str([vertex[key] for key in sorted(vertex.keys())])
        if salt is None:
            salt = ''
        return {algorithm: getattr(hashlib, algorithm)(properties.encode()+salt).hexdigest() 
                for algorithm in ['sha256', 'sha384', 'md5']}

    def compare_hashes(self, uuid1, uuid2, salt=None):
        hashes1 = self.hash_vertex(uuid1, salt)
        hashes2 = self.hash_vertex(uuid2, salt)
        return {algorithm: (hashes1[algorithm] == hashes2[algorithm]) for algorithm in ['sha256', 'sha384', 'md5']}
```
This is a very basic implementation and does not include all the features you requested. To implement the advanced properties, relationships, and multiple types of hash algorithms like SHA-512, HMAC-SHA256, etc., would need much more code. 

