```python
import csv
import sys
import os.path
from os import path

def process_csv(file):
    try:
        with open(file, 'r') as file:
            csv_reader = csv.reader(file)
            rows = list(csv_reader)
            print(""Total number of rows in the CSV file is"", len(rows))
    except FileNotFoundError:
        print('The input file was not found.')

def summary(file):
    try:
        with open(file, 'r') as file:
            csv_reader = csv.DictReader(file)
            rows = list(csv_reader)
            print(""Summary of the input file's details:\n"")
            for row in rows:
                print(row)
    except FileNotFoundError:
        print('The input file was not found.')

def export(file, output):
    try:
        with open(file, 'r') as read_obj, open(output, 'w', newline='') as write_obj:
            csv_reader = csv.DictReader(read_obj)
            csv_writer = csv.DictWriter(write_obj, fieldnames=csv_reader.fieldnames)
            csv_writer.writeheader()
            for row in csv_reader:
                csv_writer.writerow(row)
    except FileNotFoundError:
        print('The input file was not found.') 

def main():
    args = sys.argv[1:]

    if len(args) < 2 or len(args) > 3:
        print(""Invalid number of arguments, please use the script as follows:\n"" +
              ""For summary: python3 script.py <input_file> -s\n"" +
              ""For export: python3 script.py <input_file> --export <output_file>"")
        sys.exit(1)

    input_file = args[0]
    operation = args[1]

    if not path.exists(input_file):
        print('The input file was not found.')
        sys.exit(1)

    if operation == '-s' or operation == '--summary':
        summary(input_file)
    elif operation == '--export':
        if len(args) != 3:
            print(""Invalid arguments, please specify an output file for export"")
            sys.exit(1)
        else:
            output_file = args[2]
            export(input_file, output_file)
    else:
        process_csv(input_file)

if __name__ == ""__main__"":
    main()
``` 

