```python
import sys
import os
from subprocess import Popen, PIPE, STDOUT

def main():
    operation = sys.argv[1]
    csv_path = sys.argv[2]

    if not os.path.exists(csv_path):
        print(""CSV file doesn't exist."")
        return 

    if operation == 'summary':
        count = 0
        with open(csv_path, 'r') as f:
            for line in f:
                count += 1
        print(""Total rows:"",count)

    elif operation == 'export':
        p = Popen(['g++', '-std=c++14', '-o', 'main', 'main.cpp', '-lstdc++'], stdout=PIPE, stderr=STDOUT)

        for line in iter(p.stdout.readline, b''): 
            print('Compiling...', str(line))

        p = Popen(['./main'], stdout=PIPE, stderr=STDOUT)

        while True:
            line = p.stdout.readline()
            if not line: break
            print(""C++ Output:"",line.decode().strip())  

    else:
        print(""Invalid operation."")

if __name__ == ""__main__"":
    main()
```
This script first checks whether the CSV file exists and if it's a valid operation (summary or export). For 'export', it compiles the C++ code using g++, then runs the compiled program. The output is printed in Python. Note that you need to replace 'main.cpp' with your actual C++ source file name.
