import os

def extract_seq_number():
    try:
        with open('file.txt', 'r') as file:
            lines = file.readlines()

        if len(lines) > 0:
            last_line = lines[-1]
            seq_numbers = [int(s) for s in last_line.split() if s.isdigit()]

            return min(seq_numbers) # Return the minimum sequence number to handle multiple digits in a line
        else:
            print('File is empty')
    except FileNotFoundError:
        print(""The file does not exist"")
    except IOError:
        print(""An error occurred while reading the file"")
```
