```python
import argparse
import csv
import random
import os

class TaskStatus:
    def __init__(self, id, duration):
        self.id = id
        self.duration = duration

def process_csv_summary(file_path):
    if not os.path.exists(file_path):
        raise FileNotFoundError(f""File '{file_path}' does not exist."")

    with open(file_path, 'r') as csvfile:
        reader = csv.reader(csvfile)
        row_count = sum(1 for _ in reader)
    return row_count

def generate_task_status(num_tasks):
    tasks = []
    for i in range(num_tasks):
        id = i + 1  # Starting from 1 for unique IDs
        duration = random.randint(10, 60)  # Random duration between 10 to 60 seconds
        tasks.append(TaskStatus(id, duration))
    return tasks

def sort_tasks(tasks):
    return sorted(tasks, key=lambda x: x.duration)

def log_task_status(tasks):
    try:
        with open('task_status.log', 'w') as log_file:
            for task in tasks:
                log_file.write(f""Task ID: {task.id}, Duration: {task.duration} seconds\n"")
                log_file.write(""Logged successfully.\n"")
    except Exception as e:
        print(f""Error logging task status: {e}. Falling back to warning."")
        print(""Task status logged with warnings."")

def main():
    parser = argparse.ArgumentParser(description='CSV file row summary or C++ TaskStatus export.')
    parser.add_argument('operation', choices=['summary', 'export'], help='Operation type: summary or export')
    parser.add_argument('file_path', help='Path to the CSV file')

    args = parser.parse_args()

    if args.operation == 'summary':
        row_count = process_csv_summary(args.file_path)
        print(f""Summary of '{args.file_path}': {row_count} rows found."")

    elif args.operation == 'export':
        num_tasks = random.randint(5, 20)  
        tasks = generate_task_status(num_tasks)

        sorted_tasks = sort_tasks(tasks)

        log_task_status(sorted_tasks)

if __name__ == '__main__':
    main()
